@IsTest
private class SchedCapTest {
    static String obs(String v) {
        Integer b = [SELECT COUNT() FROM Account WHERE Name = 'batch-side-effect'];
        Integer s = [SELECT COUNT() FROM Account WHERE Name = 'scheduled-side-effect'];
        Integer q = [SELECT COUNT() FROM Account WHERE Name = 'queue-side-effect'];
        Integer c = [SELECT COUNT() FROM CronTrigger WHERE CronJobDetail.Name LIKE 'SchedCap%'];
        return 'OBS ' + v + ' batch=' + b + ' sched=' + s + ' queue=' + q + ' cron=' + c;
    }
    static void seed() { insert new Account(Name = 'Batch target'); }
    @IsTest static void v01AsIs() { seed(); Test.startTest(); Database.executeBatch(new SchedCapBatch(), 1); System.schedule('SchedCapA', '0 0 0 1 1 ? 2050', new SchedCapJob()); Test.stopTest(); System.assert(false, obs('v01AsIs')); }
    @IsTest static void v02SchedAlone() { seed(); Test.startTest(); System.schedule('SchedCapA', '0 0 0 1 1 ? 2050', new SchedCapJob()); Test.stopTest(); System.assert(false, obs('v02SchedAlone')); }
    @IsTest static void v03BatchAlone() { seed(); Test.startTest(); Database.executeBatch(new SchedCapBatch(), 1); Test.stopTest(); System.assert(false, obs('v03BatchAlone')); }
    @IsTest static void v04BatchSchedQueue() { seed(); Test.startTest(); Database.executeBatch(new SchedCapBatch(), 1); System.schedule('SchedCapA', '0 0 0 1 1 ? 2050', new SchedCapJob()); System.enqueueJob(new SchedCapQ()); Test.stopTest(); System.assert(false, obs('v04BatchSchedQueue')); }
    @IsTest static void v05SchedBeforeBatch() { seed(); Test.startTest(); System.schedule('SchedCapA', '0 0 0 1 1 ? 2050', new SchedCapJob()); Database.executeBatch(new SchedCapBatch(), 1); Test.stopTest(); System.assert(false, obs('v05SchedBeforeBatch')); }
    @IsTest static void v06BatchSched2099() { seed(); Test.startTest(); Database.executeBatch(new SchedCapBatch(), 1); System.schedule('SchedCapA', '0 0 0 1 1 ? 2099', new SchedCapJob()); Test.stopTest(); System.assert(false, obs('v06BatchSched2099')); }
    @IsTest static void v07Sched2099Alone() { seed(); Test.startTest(); System.schedule('SchedCapA', '0 0 0 1 1 ? 2099', new SchedCapJob()); Test.stopTest(); System.assert(false, obs('v07Sched2099Alone')); }
    @IsTest static void v08BatchDefaultScope() { seed(); Test.startTest(); Database.executeBatch(new SchedCapBatch()); System.schedule('SchedCapA', '0 0 0 1 1 ? 2050', new SchedCapJob()); Test.stopTest(); System.assert(false, obs('v08BatchDefaultScope')); }
    @IsTest static void v09SchedQueueNoBatch() { seed(); Test.startTest(); System.schedule('SchedCapA', '0 0 0 1 1 ? 2050', new SchedCapJob()); System.enqueueJob(new SchedCapQ()); Test.stopTest(); System.assert(false, obs('v09SchedQueueNoBatch')); }
    @IsTest static void v10SchedNoStartTest() { seed(); System.schedule('SchedCapA', '0 0 0 1 1 ? 2050', new SchedCapJob()); Test.startTest(); Test.stopTest(); System.assert(false, obs('v10SchedNoStartTest')); }
}

